#include <stdio.h>
#include <string.h>

int main(void) {
    char s[128];
    if (fgets(s, sizeof(s), stdin) == 0) {
        return 1;
    }
    s[strcspn(s, "\n")] = 0;
    unsigned int k;
    if (scanf("%u", &k) != 1) {
        return 1;
    }
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) {
        char *p = &s[i];
        unsigned char enc = (unsigned char)((*p) ^ (unsigned char)k);
        if (i) {
            printf(" ");
        }
        printf("%u", (unsigned int)enc);
    }
    printf("\n");
    return 0;
}

