int main(void) {
    uint32_t a, b;
    while (scanf("%u %u", &a, &b) == 2) {
        uint64_t x = a;
        uint64_t y = b;
        uint64_t result = 0;
        while (y > 0) {
            if (y & 1u) {
                result += x;
            }
            x <<= 1;
            y >>= 1;
        }
        printf("%llu\n", (unsigned long long)result);
    }
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint32_t a, b;
    while (scanf("%u %u", &a, &b) == 2) {
        if (b == 0) {
            printf("-1\n");
            continue;
        }
        uint32_t quotient = 0;
        uint32_t remainder = 0;
        for (int i = 31; i >= 0; i--) {
            remainder <<= 1;
            remainder |= (a >> i) & 1u;
            if (remainder >= b) {
                remainder -= b;
                quotient |= ((uint32_t)1 << i);
            }
        }
        printf("%u\n", quotient);
    }
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint32_t r;
    while (scanf("%u", &r) == 1) {
        uint32_t prev = r;
        prev &= r - 1u;
        uint32_t isolated = r ^ prev;
        unsigned int pos = 0;
        while (isolated > 1u) {
            isolated >>= 1;
            pos++;
        }
        printf("%u\n", pos);
    }
    return 0;
}

